SELECT p.no,course_no,title,thumbnail,m.name as instructor,price, TO_CHAR(p.regdate,'yyyy-mm-dd hh24:mi:ss') as dbday, order_status FROM course_payment p JOIN course c ON p.course_no=c.no JOIN member m ON c.instructor_no=m.member_id WHERE p.member_id=#{member_id}
AND p.order_status = #{order_status}
ORDER BY p.no DESC OFFSET #{start} ROWS FETCH NEXT 3 ROWS ONLY

	SELECT COUNT(*) FROM course_payment
	WHERE member_id=#{member_id}

        AND order_status = #{order_status}

	SELECT COUNT(*) FROM book_order
	WHERE member_id=#{member_id}

        AND order_status = #{order_status}

SELECT no, member_id, total_price, order_status, TO_CHAR(regdate, 'yyyy-MM-dd') as dbday FROM book_order WHERE member_id = #{member_id}
AND order_status = #{order_status}
ORDER BY no DESC OFFSET #{start} ROWS FETCH NEXT 3 ROWS ONLY
